<?php
namespace App\Filament\Admin\Pages;
use App\Models\Setting;
use App\Services\SiteSeoAiService;
use BackedEnum;
use Filament\Forms\Components\FileUpload;
use Filament\Schemas\Components\Section;
use Filament\Forms\Components\Textarea;
use Filament\Forms\Components\TextInput;
use Filament\Forms\Concerns\InteractsWithForms;
use Filament\Forms\Contracts\HasForms;
use Filament\Notifications\Notification;
use Filament\Pages\Page;
use Filament\Schemas\Schema;
use Filament\Support\Icons\Heroicon;
class SeoSettings extends Page implements HasForms { use InteractsWithForms; protected static string|BackedEnum|null $navigationIcon=Heroicon::MagnifyingGlass; protected static ?string $navigationLabel='SEO وإعدادات الموقع'; protected static ?string $title='SEO وإعدادات الموقع'; protected static ?int $navigationSort=2; protected string $view='filament.admin.pages.seo-settings'; public ?array $data=[]; public static function getNavigationGroup(): ?string { return 'إعدادات والنظام'; } public function mount(): void { abort_unless(auth()->user()->can('settings.show'),403); $this->form->fill(Setting::getSettings()->only($this->fields())); } public function form(Schema $schema): Schema { return $schema->components([Section::make('الصفحة الرئيسية')->description('بيانات Google ونتائج المشاركة. أنشئها بالذكاء الاصطناعي ثم عدّلها عند الحاجة.')->schema([TextInput::make('seo_home_title_ar')->label('عنوان الصفحة الرئيسية بالعربية')->maxLength(70),TextInput::make('seo_home_title_en')->label('عنوان الصفحة الرئيسية بالإنجليزية')->maxLength(70),Textarea::make('seo_home_description_ar')->label('وصف الصفحة الرئيسية بالعربية')->rows(3)->maxLength(170),Textarea::make('seo_home_description_en')->label('وصف الصفحة الرئيسية بالإنجليزية')->rows(3)->maxLength(170),TextInput::make('seo_home_keywords_ar')->label('كلمات مفتاحية بالعربية')->maxLength(500),TextInput::make('seo_home_keywords_en')->label('كلمات مفتاحية بالإنجليزية')->maxLength(500)])->columns(2),Section::make('الهوية والمشاركة')->schema([TextInput::make('seo_business_name_ar')->label('اسم النشاط بالعربية'),TextInput::make('seo_business_name_en')->label('اسم النشاط بالإنجليزية'),FileUpload::make('seo_og_image')->label('صورة المشاركة Facebook / X')->image()->directory('settings/seo')->helperText('يفضل 1200 × 630 بكسل.'),TextInput::make('seo_facebook_url')->label('رابط Facebook')->url(),TextInput::make('seo_instagram_url')->label('رابط Instagram')->url(),TextInput::make('seo_x_url')->label('رابط X')->url()])->columns(2)])->statePath('data'); } public function generate(): void { try { $this->data=array_merge($this->data ?? [],app(SiteSeoAiService::class)->generate()); $this->form->fill($this->data); Notification::make()->title('تم إنشاء مسودة SEO بالذكاء الاصطناعي')->success()->send(); } catch (\Throwable $e) { report($e); Notification::make()->title('تعذر إنشاء SEO')->body($e->getMessage())->danger()->send(); } } public function save(): void { abort_unless(auth()->user()->can('settings.update'),403); Setting::getSettings()->update($this->form->getState()); Notification::make()->title('تم حفظ إعدادات SEO')->success()->send(); } private function fields(): array { return ['seo_home_title_ar','seo_home_title_en','seo_home_description_ar','seo_home_description_en','seo_home_keywords_ar','seo_home_keywords_en','seo_og_image','seo_business_name_ar','seo_business_name_en','seo_facebook_url','seo_instagram_url','seo_x_url']; } }